use crate::model::*; pub struct App { pub fleet:Pane<Vec<FleetRow>>,pub work:Pane<WorkBuckets>,pub scroll:usize,pub quit:bool }
pub struct Pane<T>{pub content:PaneContent<T>,pub refreshing:bool}
pub enum PaneContent<T>{Loading,Fresh{value:T,read_at:chrono::DateTime<chrono::Utc>},Stale{value:T,read_at:chrono::DateTime<chrono::Utc>,failed_at:chrono::DateTime<chrono::Utc>,error:String},Unavailable{failed_at:chrono::DateTime<chrono::Utc>,error:String}}
impl<T> Pane<T>{pub fn loading()->Self{Self{content:PaneContent::Loading,refreshing:false}} pub fn fail(&mut self,at:chrono::DateTime<chrono::Utc>,error:String){self.content=match std::mem::replace(&mut self.content,PaneContent::Unavailable{failed_at:at,error:error.clone()}){PaneContent::Fresh{value,read_at}=>PaneContent::Stale{value,read_at,failed_at:at,error},PaneContent::Stale{value,read_at,..}=>PaneContent::Stale{value,read_at,failed_at:at,error},_=>PaneContent::Unavailable{failed_at:at,error}};self.refreshing=false}}
